import{_ as d,o as r,c as a,a0 as e}from"./chunks/framework.AQcSKqPn.js";const u=JSON.parse('{"title":"AI情报日报 2026-08-04","description":"","frontmatter":{"type":"page","title":"AI情报日报 2026-08-04","tags":["ai","daily-report","情报"],"created":"2026-08-04T00:00:00.000Z"},"headers":[],"relativePath":"daily/ai-report-2026-08-04.md","filePath":"daily/ai-report-2026-08-04.md","lastUpdated":1786500626000}'),o={name:"daily/ai-report-2026-08-04.md"};function i(n,t,l,s,h,p){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="ai情报日报-2026-08-04" tabindex="-1">AI情报日报 2026-08-04 <a class="header-anchor" href="#ai情报日报-2026-08-04" aria-label="Permalink to &quot;AI情报日报 2026-08-04&quot;">​</a></h1><h2 id="ai-hot-精选" tabindex="-1">AI HOT 精选 <a class="header-anchor" href="#ai-hot-精选" aria-label="Permalink to &quot;AI HOT 精选&quot;">​</a></h2><blockquote><p>数据来源：AI HOT (aihot.virxact.com)｜数字生命卡兹克 ｜ 窗口：2026-08-03 ~ 2026-08-04</p></blockquote><h3 id="模型发布-更新" tabindex="-1">模型发布/更新 <a class="header-anchor" href="#模型发布-更新" aria-label="Permalink to &quot;模型发布/更新&quot;">​</a></h3><ul><li><p><strong>Qwen3.8-Max 发布：开源最强编码与协作模型，2.4T 参数</strong> Qwen 正式发布 Qwen3.8-Max，这是 Qwen 家族迄今最强的模型，拥有 2.4T 参数（95B 激活），并首次开源 Qwen-Max 级权重，开放权重将于下周发布。</p></li><li><p><strong>商汤发布 SenseNova U1.5-Lite-Preview 开源模型</strong> 商汤推出 SenseNova U1.5-Lite-Preview，一个基于 NEO-Unify 架构的轻量级原生统一多模态模型，仅 8B-MoT 参数即可达到商业闭源模型的生成与编辑质量。</p></li></ul><h3 id="产品发布-更新" tabindex="-1">产品发布/更新 <a class="header-anchor" href="#产品发布-更新" aria-label="Permalink to &quot;产品发布/更新&quot;">​</a></h3><ul><li><p><strong>GPT-Live实时音频新架构发布</strong> GPT-Live 是一种用于实时音频的新架构和栈： GPT-Live 可以在说话的同时聆听。 为了让这种体验在 ChatGPT 规模下显得自然，我们从客户端到模型重建了语音栈。 这一新架构让音频持续流动，因此更深入的推理和工具使用不会打断对话。</p></li><li><p><strong>Cloudflare 推出 @cloudflare/computer 预览版：为智能体提供虚拟文件系统与多执行环境</strong> Cloudflare 发布 @cloudflare/computer 早期预览版，这是一个开源智能体运行时，为每个智能体提供虚拟文件系统，并支持在 isolate、容器沙箱或浏览器中执行代码。</p></li><li><p><strong>微软开源 Orchard 智能体训练框架</strong> Orchard 是一个面向研究社区的开源框架，用于跨任务类型训练和评估 AI 智能体。它降低了复杂性，同时通过让研究人员复用同一套基础设施，支持较小模型也能实现强劲性能。<a href="https://msft.it/6019a8fqP" target="_blank" rel="noreferrer">https://msft.it/6019a8fqP</a></p></li></ul><h3 id="行业动态" tabindex="-1">行业动态 <a class="header-anchor" href="#行业动态" aria-label="Permalink to &quot;行业动态&quot;">​</a></h3><ul><li><p><strong>欧盟《人工智能法案》透明度规则生效，违规最高罚 1500 万欧元</strong> 欧盟《人工智能法案》下的新透明度义务于 8 月 2 日生效，要求公司披露用户何时与 AI 模型互动，并为合成音视频和文本添加机器可读标记。欧盟还推出了一套可选的 AI 披露标签供平台采用，但标注要求本身是强制性的。违规公司面临最高 1500 万欧元（约 1720 万美元）或全球年营业额 3% 的罚款，8 月 2 日前推出的模型有 4 个月宽限期。</p></li><li><p><strong>Databricks 完成对 Panther 的收购，加速安全湖仓时代</strong> Databricks 宣布正式完成对安全数据平台 Panther 的收购，旨在加速安全湖仓（Security Lakehouse）时代。此次收购将 Panther 的安全分析能力整合进 Databricks 平台，帮助企业在统一的数据架构上运行安全运营与威胁检测工作负载。具体交易条款未披露。</p></li></ul><h3 id="论文研究" tabindex="-1">论文研究 <a class="header-anchor" href="#论文研究" aria-label="Permalink to &quot;论文研究&quot;">​</a></h3><ul><li><strong>多模态大语言模型对齐的全面研究：Apple 团队独立拆解偏好对齐各环节</strong> Apple 研究团队系统梳理了多模态大语言模型（MLLM）中的偏好对齐方法，将算法分为离线（如 DPO）与在线（如 online-DPO）两类，并发现两者结合可在特定场景下提升模型性能。团队还提出无需额外标注或外部模型的新型多模态偏好数据构建方法 Bias-Driven Hallucination Sampling（BDHS），在多项基准上取得与既有对齐工作相当的竞争力。</li></ul><h3 id="技巧与观点" tabindex="-1">技巧与观点 <a class="header-anchor" href="#技巧与观点" aria-label="Permalink to &quot;技巧与观点&quot;">​</a></h3><ul><li><p><strong>AirLLM 实现单块 4GB GPU 运行 70B 模型推理</strong> AirLLM 项目支持在单块 4GB 显存 GPU 上运行 70B 参数大模型推理，无需多卡或大规模显存配置。该项目已开源，相关讨论在 Hacker News 上获得 103 点热度，引发社区关注。</p></li><li><p><strong>关于 Astra 与数学的两则重要更新：Anthropic 数学家 24 小时复现 OpenAI 半数结果</strong> Gary Marcus 称 OpenAI 的 Astra 可能并非其宣传的突破，Anthropic 数学家 Levent Alpöge 用已公开的 Fable 模型在 24 小时内复现了 OpenAI 半数结果，质疑其真实进展。</p></li></ul><h2 id="小红书爆款-top-10" tabindex="-1">小红书爆款 TOP 10 <a class="header-anchor" href="#小红书爆款-top-10" aria-label="Permalink to &quot;小红书爆款 TOP 10&quot;">​</a></h2><blockquote><p>数据来源：RedFox 小红书单日爆款榜 ｜ 数据日期：2026-08-02</p></blockquote><table tabindex="0"><thead><tr><th>#</th><th>标题</th><th>作者(粉丝)</th><th>👍 点赞</th><th>💬 评论</th><th>⭐ 收藏</th><th>🔄 分享</th><th>互动总量</th></tr></thead><tbody><tr><td>1</td><td>互联网的记忆不该被遗忘</td><td>脆梨甜孃孃(29w+粉)</td><td>16w+</td><td>2303</td><td>2894</td><td>197</td><td><strong>16w+</strong></td></tr><tr><td>2</td><td>从此我的图层又多了一只手。</td><td>捕娱小海星(10w+粉)</td><td>9w+</td><td>662</td><td>3w+</td><td>6093</td><td><strong>13w+</strong></td></tr><tr><td>3</td><td>第一次意识到建模怪是多么恐怖的存在（cr:YuSeN.）</td><td>吗喽王哔哔(11w+粉)</td><td>12w+</td><td>744</td><td>4782</td><td>3021</td><td><strong>13w+</strong></td></tr><tr><td>4</td><td>在Neil的眼里自己是衣锦还乡 在居民眼里是大闹出生地！</td><td>菠萝盖浇饭(3w+粉)</td><td>11w+</td><td>2473</td><td>6059</td><td>1w+</td><td><strong>12w+</strong></td></tr><tr><td>5</td><td>当我第一次带女朋友回家</td><td>丸子Meme(5w+粉)</td><td>7w+</td><td>123</td><td>1w+</td><td>932</td><td><strong>9w+</strong></td></tr><tr><td>6</td><td>果然有地位 : 还是个卧铺</td><td>MIFFOR(5w+粉)</td><td>8w+</td><td>831</td><td>3141</td><td>1403</td><td><strong>9w+</strong></td></tr><tr><td>7</td><td>张若昀唐艺昕 每隔一段时间带火一个挑战</td><td>追娱大明星(27w+粉)</td><td>8w+</td><td>909</td><td>4861</td><td>2920</td><td><strong>8w+</strong></td></tr><tr><td>8</td><td>叔你丝滑的让我觉得像ai</td><td>小小汐呀(6510粉)</td><td>7w+</td><td>1828</td><td>8335</td><td>8039</td><td><strong>8w+</strong></td></tr><tr><td>9</td><td>青春没有售价 硬座直达拉萨！50个小时硬座直达 太疯狂…</td><td>古怪小琦(100w+粉)</td><td>6w+</td><td>965</td><td>1w+</td><td>1022</td><td><strong>8w+</strong></td></tr><tr><td>10</td><td>未来机器人，就应该是这样啊！</td><td>嗑学研究所(16w+粉)</td><td>7w+</td><td>1365</td><td>3383</td><td>4744</td><td><strong>7w+</strong></td></tr></tbody></table><p><strong>趋势解读：</strong> 榜单以泛娱乐/搞笑/颜值内容为主，头部互动量均在 7w+； AI 相关选题渗透进日常内容（如&quot;叔你丝滑的让我觉得像ai&quot;、&quot;未来机器人就应该是这样&quot;）， 机器人/AI 话题在泛知识类账号中表现突出；低粉账号（小小汐呀 6510粉）凭借横店 NPC 内容跻身 TOP10， 说明强现场感/剧情类内容仍有冷启动机会。</p><hr><p><em>生成时间：2026-08-04 09:22 ｜ AI HOT + RedFox 自动汇总</em></p>',19)])])}const g=d(o,[["render",i]]);export{u as __pageData,g as default};
